private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> left = node.left;
    if (left == null) {
        // Cannot rotate if there is no left child
        return node;
    }

    // Perform rotation
    node.left = left.right;
    if (left.right != null) {
        left.right.parent = node;
    }
    left.right = node;

    // Update parent links
    left.parent = node.parent;
    node.parent = left;

    // If the original node had a parent, update its child reference
    if (left.parent != null) {
        if (left.parent.left == node) {
            left.parent.left = left;
        } else if (left.parent.right == node) {
            left.parent.right = left;
        }
    }

    return left;
}

