        s = e;
    }
    return ranges;
}

static long compressTimeBucket(long timeBucket,int dayStep){
    // Validate dayStep
    if(dayStep <= 0){
        throw new IllegalArgumentException("dayStep must be positive");
    }
    if(timeBucket <= 0){
        throw new IllegalArgumentException("timeBucket must be positive");
    }
    // Extract year, month, day
    int year = (int)(timeBucket / 10000);
    int month = (int)((timeBucket % 10000) / 100);
    int day = (int)(timeBucket % 100);
    // Basic range checks
    if(month < 1 || month > 12){
        throw new IllegalArgumentException("Invalid month in timeBucket: " + month);
    }
    if(day < 1 || day > 31){
        throw new IllegalArgumentException("Invalid day in timeBucket: " + day);
    }
    // Validate day against month length
    int daysInMonth;
    try{
        java.time.YearMonth ym = java.time.YearMonth.of(year, month);
        daysInMonth = ym.lengthOfMonth();
    }catch(java.time.DateTimeException e){
        throw new IllegalArgumentException("Invalid date in timeBucket: " + timeBucket, e);
    }
    if(day > daysInMonth){
        throw new IllegalArgumentException("Day exceeds month length: " + day + " > " + daysInMonth);
    }
    // Compute compressed day
    int newDay = ((day - 1) / dayStep) * dayStep + 1;
    // Ensure newDay does not exceed month length (shouldn't happen)
    if(newDay > daysInMonth){
        newDay = daysInMonth;
    }
    return (long)year * 10000L + (long)month * 100L + (long)newDay;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
