    if (request instanceof AtmosphereRequest) {
        return (AtmosphereRequest) request;
    }
    try {
        return new org.atmosphere.cpr.AtmosphereRequestImpl(request);
    } catch (Exception e) {
        throw new RuntimeException("Failed to wrap HttpServletRequest", e);
    }
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if (str == null) {
        return lb;
    }
    try {
        byte[] bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        // Attempt to write the byte array in bulk if the method exists
        try {
            lb.write(bytes, 0, bytes.length);
        } catch (NoSuchMethodError | UnsupportedOperationException e) {
            // Fallback to writing byte by byte
            for (byte b : bytes) {
                try {
                    lb.write(b);
                } catch (Exception inner) {
                    throw new RuntimeException("Failed to write byte to LinkedBuffer", inner);
                }
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to encode string to UTF-8 and write to LinkedBuffer", e);
    }
    return lb;
}

public static String findAndSubst(String key, java.util.Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }
    // Perform variable substitution on the found value.
    // Supports ${var} and ${var:default} syntax, with recursive resolution up to a depth limit.
    String result = value;
    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)}");
    int maxDepth = 10; // prevent infinite recursion
    for (int depth = 0; depth < maxDepth; depth++) {
        java.util.regex.Matcher matcher = pattern.matcher(result);
        if (!matcher.find()) {
            break; // no more placeholders
        }
        StringBuffer sb = new StringBuffer();
        matcher.reset();
        while (matcher.find()) {
            String expr = matcher.group(1);
            String replacement;
            int colonIndex = expr.indexOf(':');
            if (colonIndex >= 0) {
                String varName = expr.substring(0, colonIndex);
                String defaultVal = expr.substring(colonIndex + 1);
                String propVal = props.getProperty(varName);
                replacement = (propVal != null) ? propVal : defaultVal;
            } else {
                String propVal = props.getProperty(expr);
                replacement = (propVal != null) ? propVal : "";
            }
            // Escape backslashes and dollar signs in the replacement string
            replacement = java.util.regex.Matcher.quoteReplacement(replacement);
            matcher.appendReplacement(sb, replacement);
        }
        matcher.appendTail(sb);
        result = sb.toString();
    }
    return result;
}

