private static boolean endsWith(final String str, final String suffix, final boolean ignoreCase) {
    // Both null => true
    if (str == null && suffix == null) {
        return true;
    }
    // One is null => false
    if (str == null || suffix == null) {
        return false;
    }
    int strLen = str.length();
    int suffixLen = suffix.length();
    // Suffix longer than string => cannot match
    if (suffixLen > strLen) {
        return false;
    }
    int start = strLen - suffixLen;
    // Use regionMatches to handle case sensitivity
    return str.regionMatches(ignoreCase, start, suffix, 0, suffixLen);
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }
    String path = u.getPath();
    List<PathSegmentImpl> segments = new ArrayList<>();
    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Split on '/' keeping empty segments
    String[] parts = path.split("/", -1);
    int start = 0;
    // If the path is absolute, ignore the leading empty segment caused by the leading '/'
    if (!parts[0].isEmpty()) {
        // Path is relative, keep all parts
        start = 0;
    } else {
        // Path is absolute, skip the first empty part
        start = 1;
    }
    for (int i = start; i < parts.length; i++) {
        String part = parts[i];
        String value = part;
        if (decode) {
            try {
                value = java.net.URLDecoder.decode(part, "UTF-8");
            } catch (java.io.UnsupportedEncodingException e) {
                throw new IllegalArgumentException("UTF-8 encoding not supported", e);
            }
        }
        segments.add(new PathSegmentImpl(value));
    }
    return segments;
}

