public long readRawVarint64() throws IOException {
    long result = 0;
    int shift = 0;
    for (int i = 0; i < 10; i++) {
        int b = readRawByte(); // read a single byte from the underlying stream
        result |= (long) (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            return result;
        }
        shift += 7;
    }
    // If we get here, the varint is too long (more than 10 bytes)
    throw new IOException("Malformed varint: too many bytes");
}

