@Override
public void write(final byte b[], final int off, final int len) throws IOException {
    // Validate arguments
    if (b == null) {
        throw new NullPointerException("The byte array is null");
    }
    if (off < 0 || len < 0 || off > b.length || len > b.length - off) {
        throw new IndexOutOfBoundsException(
            "Offset and length must be non-negative and within the bounds of the array");
    }
    if (len == 0) {
        return; // nothing to write
    }

    // Calculate new count and check for integer overflow
    int newCount = count + len;
    if (newCount < 0) { // overflow
        throw new IOException("Buffer overflow");
    }

    // Expand buffer if necessary
    if (newCount > buf.length) {
        int newCapacity = Math.max(buf.length << 1, newCount);
        byte[] newBuf = new byte[newCapacity];
        System.arraycopy(buf, 0, newBuf, 0, count);
        buf = newBuf;
    }

    // Copy data into buffer
    System.arraycopy(b, off, buf, count, len);
    count = newCount;
}

public static final <V> void swap(V[] arr, int i, int j) {
    if (arr == null) {
        throw new NullPointerException("Array is null");
    }
    int len = arr.length;
    if (i < 0 || i >= len || j < 0 || j >= len) {
        throw new IndexOutOfBoundsException(
            "Index out of bounds: i=" + i + ", j=" + j + ", length=" + len);
    }
    if (i == j) {
        return;
    }
    V temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}

public Boolean isPartialContentResponse() {
    try {
        // If the response object is not available, we cannot determine the status code.
        if (response == null) {
            return Boolean.FALSE;
        }
        // Attempt to retrieve the status code. The exact method name may vary depending on the HTTP client library.
        // Commonly used methods are getStatusCode() or statusCode().
        int statusCode;
        try {
            statusCode = response.getStatusCode();
        } catch (NoSuchMethodError | IllegalAccessError | IllegalArgumentException e) {
            // Fallback to the alternative method name
            statusCode = response.statusCode();
        }
        return statusCode == 206 ? Boolean.TRUE : Boolean.FALSE;
    } catch (Exception e) {
        // Any unexpected exception should result in a safe default of false.
        return Boolean.FALSE;
    }
}

