protected void addToIndex(V sourceVertex, V targetVertex, E e) {
    // Validate inputs
    if (sourceVertex == null || targetVertex == null || e == null) {
        throw new IllegalArgumentException("Source vertex, target vertex, and edge must not be null");
    }

    // Lazily initialize the index if it hasn't been created yet
    if (index == null) {
        index = new java.util.HashMap<>();
    }

    // Retrieve or create the map for the source vertex
    java.util.Map<V, java.util.List<E>> targetMap =
            index.computeIfAbsent(sourceVertex, k -> new java.util.HashMap<>());

    // Retrieve or create the list of edges for the target vertex
    java.util.List<E> edgeList =
            targetMap.computeIfAbsent(targetVertex, k -> new java.util.ArrayList<>());

    // Add the edge to the list
    edgeList.add(e);
}

