public static Pair<Box2D,Box2D> splitAlongXAxis(Box2D box){
    if (box == null) {
        throw new IllegalArgumentException("box cannot be null");
    }
    double minX = box.getMinX();
    double maxX = box.getMaxX();
    double minY = box.getMinY();
    double maxY = box.getMaxY();
    if (minX > maxX || minY > maxY) {
        throw new IllegalArgumentException("Invalid box coordinates");
    }
    double midX = (minX + maxX) / 2.0;
    Box2D left = new Box2D(minX, minY, midX, maxY);
    Box2D right = new Box2D(midX, minY, maxX, maxY);
    return new Pair<>(left, right);
}

private void enlarge(final int size) {
    if (size <= 0) {
        return; // nothing to enlarge
    }
    // If the underlying array is not yet allocated, create it with the requested size.
    if (bytes == null) {
        bytes = new byte[size];
        return;
    }

    int oldCap = bytes.length;
    // Compute a new capacity that is at least oldCap + size.
    // Prefer doubling the capacity to reduce frequent reallocations.
    long newCapLong = (long) oldCap * 2;
    if (newCapLong < 0) { // overflow
        newCapLong = Integer.MAX_VALUE;
    }
    int newCap = (int) newCapLong;
    if (newCap < oldCap + size) {
        newCap = oldCap + size;
        if (newCap < 0) { // overflow
            newCap = Integer.MAX_VALUE;
        }
    }

    byte[] newBytes = new byte[newCap];
    System.arraycopy(bytes, 0, newBytes, 0, oldCap);
    bytes = newBytes;
}

