public static String capitalize(String name){
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the first two characters are both uppercase, leave unchanged
    if (len > 1 && Character.isUpperCase(name.charAt(0)) && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, capitalize the first character
    char first = Character.toUpperCase(name.charAt(0));
    if (len == 1) {
        return String.valueOf(first);
    }
    return first + name.substring(1);
}

public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    if (node == null) {
        return 0;
    }
    int total = 0;
    LinkedBuffer current = node;
    while (current != null) {
        byte[] buf = null;
        int size = 0;
        try {
            buf = current.getBuffer();
            size = current.getSize();
        } catch (Exception e) {
            // If the LinkedBuffer does not expose getBuffer/getSize, skip this node
            current = current.getNext();
            continue;
        }
        if (buf == null || size <= 0) {
            current = current.getNext();
            continue;
        }
        // Ensure we do not write beyond the buffer length
        int writeSize = Math.min(size, buf.length);
        out.write(buf, 0, writeSize);
        total += writeSize;
        current = current.getNext();
    }
    return total;
}

