private void putAbstractTypes(final int start, final int end) {
    // Validate inputs
    if (currentFrame == null) {
        throw new IllegalStateException("currentFrame is null");
    }
    if (stackMapTableEntries == null) {
        throw new IllegalStateException("stackMapTableEntries is null");
    }
    if (start < 0 || end > currentFrame.length || start > end) {
        throw new IllegalArgumentException(
                "Invalid start (" + start + ") or end (" + end + ") indices");
    }

    // Write each type in the JVMS verification_type_info format
    for (int i = start; i < end; i++) {
        int type = currentFrame[i];
        int tag = type & 0xFF; // low 8 bits hold the tag

        stackMapTableEntries.putByte(tag);

        // For OBJECT and UNINITIALIZED types, write the following 2-byte value
        switch (tag) {
            case OBJECT:
            case UNINITIALIZED:
                stackMapTableEntries.putShort(type);
                break;
            default:
                // No additional data for other tags
                break;
        }
    }
}

public void readFrom(final InputStream in) throws IOException {
    if (in == null) {
        throw new NullPointerException("InputStream cannot be null");
    }
    // Read all bytes from the input stream into a temporary buffer
    ByteArrayOutputStream baos = new ByteArrayOutputStream();
    byte[] chunk = new byte[8192];
    int read;
    while ((read = in.read(chunk)) != -1) {
        baos.write(chunk, 0, read);
    }
    byte[] data = baos.toByteArray();

    // Replace the existing buffer with the new data
    this.buffer = data;
    // Reset the read pointer to the start
    this.pos = 0;
    // Update the limit to the new buffer length
    this.limit = data.length;
}

