public static int nextPrime(int desiredCapacity) {
    // Handle non-positive or very small capacities
    if (desiredCapacity <= 2) {
        return 2;
    }
    // Start from the desired capacity, adjust to an odd number if necessary
    int candidate = desiredCapacity;
    if (candidate % 2 == 0) {
        candidate++; // make it odd
    }
    // Loop until a prime is found
    while (true) {
        // Avoid integer overflow
        if (candidate <= 0) {
            throw new IllegalArgumentException("No prime found within int range for desiredCapacity: " + desiredCapacity);
        }
        if (isPrime(candidate)) {
            return candidate;
        }
        // Increment by 2 to stay on odd numbers
        candidate += 2;
    }
}

/**
 * Checks whether a given integer is prime.
 * Assumes n > 1.
 */
private static boolean isPrime(int n) {
    if (n <= 3) {
        return n > 1;
    }
    if (n % 2 == 0) {
        return false;
    }
    int sqrtN = (int) Math.sqrt(n);
    for (int i = 3; i <= sqrtN; i += 2) {
        if (n % i == 0) {
            return false;
        }
    }
    return true;
}

