        String distPath = System.getProperty("dist.path");
        if (distPath == null || distPath.trim().isEmpty()) {
            distPath = "./dist";
        }

        java.nio.file.Path path = java.nio.file.Paths.get(distPath);

        // If the path does not exist, attempt to create it
        if (!java.nio.file.Files.exists(path)) {
            java.nio.file.Files.createDirectories(path);
        } else if (!java.nio.file.Files.isDirectory(path)) {
            throw new java.io.IOException("Configured dist path is not a directory: " + distPath);
        }
    } catch (java.nio.file.InvalidPathException e) {
        System.err.println("Invalid distribution path: " + e.getInput() + " (" + e.getMessage() + ")");
    } catch (java.io.IOException e) {
        System.err.println("Failed to initialize distribution path: " + e.getMessage());
    } catch (SecurityException e) {
        System.err.println("Security exception while initializing distribution path: " + e.getMessage());
    }
}

@Override public String readString() throws IOException {
    // Read the length of the string (assumed to be a 4-byte integer)
    int length = in.readInt();
    if (length < 0) {
        throw new IOException("Negative string length: " + length);
    }
    // Allocate a byte array to hold the string data
    byte[] bytes = new byte[length];
    int offset = 0;
    // Read bytes until the expected length is reached
    while (offset < length) {
        int read = in.read(bytes, offset, length - offset);
        if (read == -1) {
            throw new java.io.EOFException("Unexpected end of stream while reading string");
        }
        offset += read;
    }
    // Convert the byte array to a UTF-8 string
    return new String(bytes, java.nio.charset.StandardCharsets.UTF_8);
