public static String unescapeJava(String str) throws Exception {
    if (str == null) {
        return null;
    }
    StringBuilder sb = new StringBuilder(str.length());
    int len = str.length();
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (c == '\\' && i + 1 < len) {
            char next = str.charAt(i + 1);
            switch (next) {
                case 'b':
                    sb.append('\b');
                    i++;
                    break;
                case 't':
                    sb.append('\t');
                    i++;
                    break;
                case 'n':
                    sb.append('\n');
                    i++;
                    break;
                case 'f':
                    sb.append('\f');
                    i++;
                    break;
                case 'r':
                    sb.append('\r');
                    i++;
                    break;
                case '\"':
                    sb.append('\"');
                    i++;
                    break;
                case '\'':
                    sb.append('\'');
                    i++;
                    break;
                case '\\':
                    sb.append('\\');
                    i++;
                    break;
                case 'u':
                    // Unicode escape: \uXXXX
                    if (i + 5 >= len) {
                        throw new IllegalArgumentException("Incomplete Unicode escape at position " + i);
                    }
                    String hex = str.substring(i + 2, i + 6);
                    try {
                        int code = Integer.parseInt(hex, 16);
                        sb.append((char) code);
                    } catch (NumberFormatException e) {
                        throw new IllegalArgumentException("Invalid Unicode escape '\\u" + hex + "' at position " + i);
                    }
                    i += 5; // skip \uXXXX
                    break;
                default:
                    // Octal escape: up to three octal digits (0-7)
                    if (next >= '0' && next <= '7') {
                        int j = i + 1;
                        int end = j;
                        while (end < len && end - j < 3 && str.charAt(end) >= '0' && str.charAt(end) <= '7') {
                            end++;
                        }
                        String oct = str.substring(j, end);
                        try {
                            int code = Integer.parseInt(oct, 8);
                            sb.append((char) code);
                        } catch (NumberFormatException e) {
                            throw new IllegalArgumentException("Invalid octal escape '\\" + oct + "' at position " + i);
                        }
                        i = end - 1;
                    } else {
                        // Unknown escape sequence
                        throw new IllegalArgumentException("Unknown escape sequence '\\" + next + "' at position " + i);
                    }
                    break;
            }
        } else {
            sb.append(c);
        }
    }
    return sb.toString();
}

