private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("Predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("Start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("Stop node must not be null");
    }

    OuterFaceCirculator circ = new OuterFaceCirculator(start, dir);

    // If the start node is the stop node, return immediately
    if (start == stop) {
        return circ;
    }

    // Use a visited set to guard against infinite loops
    java.util.Set<Node> visited = new java.util.HashSet<>();
    visited.add(start);

    while (true) {
        Node current = circ.getNode();

        // Check predicate
        if (predicate.test(current)) {
            return circ;
        }

        // Check if we reached the stop node
        if (current == stop) {
            return circ;
        }

        // If we have looped back to a previously visited node, break to avoid infinite loop
        if (!visited.add(current)) {
            return circ;
        }

        // Move to the next node in the specified direction
        circ.next();
    }
}

