public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must be non-negative");
    }
    // Nothing to do if length is zero
    if (byteLength == 0) {
        return this;
    }

    // Ensure capacity for the new data
    int newLength = this.length + byteLength;
    if (this.data == null) {
        // No existing data, create new array
        this.data = new byte[newLength];
    } else if (newLength > this.data.length) {
        // Need to grow the array
        int newCapacity = Math.max(this.data.length * 2, newLength);
        byte[] newData = new byte[newCapacity];
        System.arraycopy(this.data, 0, newData, 0, this.length);
        this.data = newData;
    }

    // Copy bytes or fill with zeros if byteArrayValue is null
    if (byteArrayValue == null) {
        // Fill the new region with zeros
        java.util.Arrays.fill(this.data, this.length, newLength, (byte) 0);
    } else {
        // Validate offset and length against source array
        if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
            throw new IndexOutOfBoundsException("byteOffset out of bounds");
        }
        if (byteLength > byteArrayValue.length - byteOffset) {
            throw new IndexOutOfBoundsException("byteLength extends beyond source array");
        }
        System.arraycopy(byteArrayValue, byteOffset, this.data, this.length, byteLength);
    }

    // Update the logical length
    this.length = newLength;
    return this;
}

