        // There are unvisited vertices if the number of visited vertices
        // is less than the total number of vertices in the graph
        return visited.size() < vertices.size();
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Error determining if there are unvisited vertices", e);
    }
