    // Ensure this bucket is part of a hash table
    if (hashTable == null) {
        throw new IllegalStateException("Bucket is not attached to a hash table");
    }
    // Validate bucket index
    if (bucketIndex < 0 || bucketIndex >= hashTable.buckets.length) {
        throw new IllegalStateException("Invalid bucket index");
    }
    // Unlink from previous bucket
    if (prev != null) {
        prev.next = this.next;
    } else {
        // This bucket is the head of the chain
        hashTable.buckets[bucketIndex] = this.next;
    }
    // Unlink from next bucket
    if (this.next != null) {
        this.next.prev = this.prev;
    }
    // Clear references
    this.next = null;
    this.prev = null;
    this.hashTable = null;
}

