public List<SequenceRange> buildSequenceRanges(){
    List<SequenceRange> ranges = new java.util.ArrayList<>();
    try {
        if (currentProfiles == null) {
            return ranges;
        }
        for (Profile profile : currentProfiles) {
            if (profile == null) {
                continue;
            }
            List<Segment> segments = profile.getSegments();
            if (segments == null) {
                continue;
            }
            for (Segment seg : segments) {
                if (seg == null) {
                    continue;
                }
                int start = seg.getStart();
                int end = seg.getEnd();
                if (start <= end) {
                    ranges.add(new SequenceRange(start, end));
                }
            }
        }
    } catch (Exception e) {
        // In case of unexpected errors, return what has been collected so far
    }
    return ranges;
}

