private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null || bounds.isEmpty()) {
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    int[] suffixArr = new int[n];
    long suffixSum = 0L;
    for (int i = n - 1; i >= 0; i--) {
        int val = bounds.get(i);
        suffixSum += val;
        suffixArr[i] = (int) suffixSum;
    }
    List<Integer> suffixList = new ArrayList<>(n);
    for (int val : suffixArr) {
        suffixList.add(val);
    }
    return new Pair<>(suffixList, suffixSum);
}

public static final <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) {
        throw new NullPointerException("Array must not be null");
    }
    int len = arr.length;
    if (from < 0 || to < 0 || from >= len || to >= len) {
        throw new IllegalArgumentException("Indices out of bounds: from=" + from + ", to=" + to + ", length=" + len);
    }
    if (from > to) {
        throw new IllegalArgumentException("from index must be less than or equal to to index: from=" + from + ", to=" + to);
    }
    while (from < to) {
        V temp = arr[from];
        arr[from] = arr[to];
        arr[to] = temp;
        from++;
        to--;
    }
}

private static boolean startsWith(final String str, final String prefix, final boolean ignoreCase) {
    // If both are null, consider it a match
    if (str == null) {
        return prefix == null;
    }
    // If the string is not null but the prefix is null, it's not a match
    if (prefix == null) {
        return false;
    }
    // If the prefix is longer than the string, it cannot match
    if (prefix.length() > str.length()) {
        return false;
    }
    // Use regionMatches for case-insensitive comparison if requested
    if (ignoreCase) {
        return str.regionMatches(true, 0, prefix, 0, prefix.length());
    }
    // Otherwise use the standard startsWith
    return str.startsWith(prefix);
}

