public void putAllWriteable(BeanMap map){
    if (map == null) {
        throw new IllegalArgumentException("map cannot be null");
    }
    // Copy entries to avoid ConcurrentModificationException if map == this
    java.util.List<java.util.Map.Entry<?, ?>> entries = new java.util.ArrayList<>(map.entrySet());
    for (java.util.Map.Entry<?, ?> entry : entries) {
        Object keyObj = entry.getKey();
        if (keyObj == null) {
            continue;
        }
        String key = keyObj.toString();
        java.beans.PropertyDescriptor pd;
        try {
            pd = map.getPropertyDescriptor(key);
        } catch (Exception e) {
            // If property descriptor cannot be retrieved, skip this entry
            continue;
        }
        if (pd == null) {
            continue;
        }
        // Only consider properties that are both readable and writable
        if (pd.getReadMethod() != null && pd.getWriteMethod() != null) {
            try {
                this.put(key, entry.getValue());
            } catch (Exception e) {
                // Ignore any exception from put (e.g., type mismatch)
            }
        }
    }
}

