public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Validate inputs
    if (table == null || pane == null) {
        throw new IllegalArgumentException("Table and pane must not be null");
    }
    if (row < 0 || row >= table.getRowCount()) {
        throw new IllegalArgumentException("Row index out of bounds");
    }
    // Ensure the table is the view of the provided JScrollPane
    if (pane.getViewport().getView() != table) {
        throw new IllegalArgumentException("Table does not belong to the specified JScrollPane");
    }

    Runnable task = () -> {
        try {
            // Select the specified row
            table.setRowSelectionInterval(row, row);
            // Scroll to make the row visible
            java.awt.Rectangle rect = table.getCellRect(row, 0, true);
            if (rect != null) {
                table.scrollRectToVisible(rect);
            }
            // Delay repaint to allow the table to paint the newly selected row
            javax.swing.Timer repaintTimer = new javax.swing.Timer(50, e -> {
                table.repaint();
                ((javax.swing.Timer) e.getSource()).stop();
            });
            repaintTimer.setRepeats(false);
            repaintTimer.start();
        } catch (Exception ex) {
            // Log or rethrow as unchecked to avoid swallowing errors
            throw new RuntimeException("Failed to select row in JTable", ex);
        }
    };

    // Ensure the UI updates happen on the Event Dispatch Thread
    if (java.awt.EventQueue.isDispatchThread()) {
        task.run();
    } else {
        java.awt.EventQueue.invokeLater(task);
    }
}

public ByteVector putInt(final int intValue){
    // Ensure the buffer has enough space for 4 more bytes
    int newPos = pos + 4;
    if (newPos > buf.length) {
        // Double the buffer size or grow to the required size, whichever is larger
        int newSize = Math.max(buf.length * 2, newPos);
        if (newSize < 0) { // overflow protection
            throw new OutOfMemoryError("Required buffer size too large");
        }
        byte[] newBuf = new byte[newSize];
        System.arraycopy(buf, 0, newBuf, 0, buf.length);
        buf = newBuf;
    }
    // Write the int in big-endian order
    buf[pos]     = (byte)(intValue >>> 24);
    buf[pos + 1] = (byte)(intValue >>> 16);
    buf[pos + 2] = (byte)(intValue >>> 8);
    buf[pos + 3] = (byte)intValue;
    pos = newPos;
    return this;
}

public static boolean arrayequals(byte[] a, byte[] b, int count) {
    // Comparing zero bytes is always true
    if (count == 0) {
        return true;
    }
    // Null arrays cannot be compared unless count is zero
    if (a == null || b == null) {
        return false;
    }
    // Negative count is invalid
    if (count < 0) {
        return false;
    }
    // Ensure we don't read beyond array bounds
    if (count > a.length || count > b.length) {
        return false;
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    if (nameStart < 0 || nameStart > buf.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }
    // Extract the name portion starting at nameStart
    String name = buf.substring(nameStart);
    if (name == null) {
        return;
    }
    String trimmed = name.trim();
    if (trimmed.isEmpty()) {
        return;
    }
    // Split the name into words separated by whitespace
    String[] parts = trimmed.split("\\s+");
    StringBuilder abbr = new StringBuilder();
    for (String part : parts) {
        if (!part.isEmpty()) {
            abbr.append(part.charAt(0)).append('.');
        }
    }
    if (abbr.length() > 0) {
        buf.append(abbr);
    }
}

