private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        return false;
    }
    int size = vertices.size();
    if (size <= 1) {
        return true;
    }
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < size; i++) {
        V vi = list.get(i);
        if (vi == null) {
            return false;
        }
        for (int j = i + 1; j < size; j++) {
            V vj = list.get(j);
            if (vj == null) {
                return false;
            }
            try {
                if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                    return false;
                }
            } catch (IllegalArgumentException e) {
                return false;
            }
        }
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("Input list cannot be null");
    }
    int size = keys.size();
    List<Integer> result = new ArrayList<>(size);
    if (size == 0) {
        return result;
    }
    // Convert keys to Integer list, validating types
    List<Integer> intKeys = new ArrayList<>(size);
    for (K k : keys) {
        if (k == null) {
            throw new IllegalArgumentException("Key cannot be null");
        }
        if (!(k instanceof Integer)) {
            throw new IllegalArgumentException("All keys must be of type Integer");
        }
        intKeys.add((Integer) k);
    }
    // Create a sorted copy
    List<Integer> sorted = new ArrayList<>(intKeys);
    Collections.sort(sorted);
    // Map each key to its maximum lower bound
    Map<Integer, Integer> lowerMap = new HashMap<>();
    Integer lastDistinct = null;
    for (Integer val : sorted) {
        lowerMap.put(val, lastDistinct);
        if (!val.equals(lastDistinct)) {
            lastDistinct = val;
        }
    }
    // Build result preserving original order
    for (Integer val : intKeys) {
        result.add(lowerMap.get(val));
    }
    return result;
}

