public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath must not be null");
    }

    // Determine if the original path is absolute (starts with '/')
    boolean isAbsolute = path.startsWith("/");

    // Split the base path into components, ignoring empty parts
    String[] baseParts = path.split("/");
    java.util.List<String> stack = new java.util.ArrayList<>();
    for (String part : baseParts) {
        if (!part.isEmpty()) {
            stack.add(part);
        }
    }

    // Split the relative path into components
    String[] relParts = relativePath.split("/");
    for (String part : relParts) {
        if (part.isEmpty() || part.equals(".")) {
            // Skip empty or current directory references
            continue;
        } else if (part.equals("..")) {
            if (!stack.isEmpty()) {
                stack.remove(stack.size() - 1);
            } else {
                // If stack is empty and we go up, we stay at root (do nothing)
            }
        } else {
            stack.add(part);
        }
    }

    // Build the resulting path
    StringBuilder result = new StringBuilder();
    if (isAbsolute) {
        result.append("/");
    }
    for (int i = 0; i < stack.size(); i++) {
        if (i > 0) {
            result.append("/");
        }
        result.append(stack.get(i));
    }

    // If the result is empty and the original path was absolute, return "/"
    if (result.length() == 0 && isAbsolute) {
        return "/";
    }

    return result.toString();
}

