static String[] toNoNullStringArray(Object[] array){
    // Return null if the input array itself is null
    if (array == null) {
        return null;
    }

    // Count non‑null elements
    int nonNullCount = 0;
    for (Object obj : array) {
        if (obj != null) {
            nonNullCount++;
        }
    }

    // If there are no nulls, simply return the original array cast to String[]
    if (nonNullCount == array.length) {
        try {
            return (String[]) array;
        } catch (ClassCastException e) {
            // The array is not actually a String[]; fall through to create a new array
        }
    }

    // Build a new array without nulls
    String[] result = new String[nonNullCount];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            // Attempt to cast each element to String; if it fails, throw a clear exception
            try {
                result[idx++] = (String) obj;
            } catch (ClassCastException e) {
                throw new IllegalArgumentException(
                    "Array contains non‑String element: " + obj, e);
            }
        }
    }
    return result;
}

