    }
    for (int i = 0; i < subLen; i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

private static final String[] cache = new String[128];
static {
    for (int i = 0; i < 128; i++) {
        cache[i] = String.valueOf((char) i);
    }
}

public static String toString(final char ch) {
    if (ch < 128) {
        return cache[ch];
    }
    return String.valueOf(ch);
}

public int readTag() throws IOException {
    try {
        int tag = input.readRawVarint32();
        // In protobuf, tag 0 is not a valid field tag; treat it as end of message.
        return tag == 0 ? 0 : tag;
    } catch (EOFException e) {
        // Reached end of input – return 0 to signal EOF.
        return 0;
    }
}

private String buildContentRange() {
    try {
        // Validate range boundaries
        if (start < 0 || end < start) {
            throw new IllegalArgumentException(
                "Invalid range: start=" + start + ", end=" + end);
        }

        // If total length is unknown, use '*' as per RFC 7233
        if (total <= 0) {
            return "bytes " + start + "-" + end + "/*";
        }

        // Build the standard Content-Range header value
        return "bytes " + start + "-" + end + "/" + total;
    } catch (Exception e) {
        // Wrap any unexpected exception in a runtime exception
        throw new RuntimeException("Failed to build Content-Range header", e);
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist or is not a regular file: " + file);
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return java.util.Collections.emptyList();
    }

    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();

    try (java.io.BufferedReader reader = new java.io.BufferedReader(new java.io.FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }

            ThreadSnapshot snapshot;
            try {
                // Assume ThreadSnapshot has a static parseFromString method
                snapshot = ThreadSnapshot.parseFromString(line);
            } catch (Exception e) {
                // Skip lines that cannot be parsed
                continue;
            }

            if (snapshot == null) {
                continue;
            }

            long ts = snapshot.getTimestamp();
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                if (range == null) {
                    continue;
                }
                long start = range.getStartTime();
                long end = range.getEndTime();
                if (ts >= start && ts <= end) {
                    result.add(snapshot);
                    break;
                }
            }
        }
    }

    return result;
}
